mapper.select:
select r.id, r.reporter_id, r.target_id, r.report_reason as reason, r.report_content as reportContent, r.created_time, r.handle_status as status, c.content as targetContent, u.username as reporterName, u.avatar as reporterAvatar from user_report as r left join comment as c on r.target_type = 2 and r.target_id = c.id left join user as u on c.user_id = u.id
r.target_type = 2
and r.handle_status = #{status}
and r.report_reason = #{reason}
and ( u.username like concat('%', #{key}, '%') or c.content like concat('%', #{key}, '%') )
order by r.created_time desc
